fn char_ct(h: &mut MgHost, vm: &mut V) -> R {
    let (this, character, pos) = (vm.a(0), vm.a(1), vm.a(2));
    let p = if pos != 0 { read_v3(vm, pos) } else { [0.; 3] };
    let vt = vm.img.addr("__vt__23PhysicsDynamicCharacter");
    if let Some(vt) = vt {
