    let ud = vm.alloc_zeroed(0x10, 16);
    vm.w32(ud + 4, 4);
    vm.w32(ud + 0xc, this);
    if let Some(c) = h.phys.chars.get_mut(&this) {
        c.user_data = ud;
    }
    Ok(())
}

